    const tracked=WEAPON[g.focusRecipe]||WEAPON[HERO[g.hero].weapon],tw=g.weapons.find(w=>w.id===tracked.id),tr=g.relics.find(r=>r.id===tracked.relic);set('recipe-target',tw?.evolved?'✦ '+tracked.evolution+' 완성':tracked.name+' '+(tw?.level||0)+'/5 · '+RELIC[tracked.relic].name+' '+(tr?.level||0)+'/1');
