  banner(title,eye,duration){clearTimeout(this.bannerTimer);const el=document.getElementById('arena-banner');if(!el)return;document.getElementById('banner-title').textContent=title;document.getElementById('banner-eye').textContent=eye;el.classList.add('visible');this.bannerTimer=setTimeout(()=>el.classList.remove('visible'),duration);}
